    private async Task ProcessNextFile()
    {
        if (!isAuthenticated || !isConnected) return;

        if (files.Count == 0)
        {
            UpdateStatus("Todos os arquivos atualizados!");
            return;
        }

        var file = files[0];
        currentFileName = file.FileName;
        totalBytes = file.Size;
        downloadedBytes = 0;
        progressPercent = 0;
        isDownloading = true;
        retryCount = 0;
        lastRetryTime = DateTime.Now;

        UpdateStatus($"Preparando para iniciar o download de @{file.FileName}...");

        try
        {
            await DownloadAndSaveFile(file);
        }
        catch (OperationCanceledException)
        {
            UpdateStatus("Download cancelado pelo usuário.");
            isDownloading = false;
        }
        catch (Exception ex)
        {
            HandleDownloadError(ex, file);
        }
    }

    private async Task DownloadAndSaveFile(PatchFile file)
    {
        while (true)
        {
            // Lógica de Verificação de Existência e Hash
            if (await FileExistsAndMatchesHash(file))
            {
                UpdateStatus($"Arquivo '{file.FileName}' já está atualizado. Pulando...");
                files.RemoveAt(0);
                await Task.Delay(1000);
                continue;
            }

            // Tentativa de Download com Retrieda
            if (retryCount > 0)
            {
                UpdateStatus($"Reiniciando o download (Tentativa {retryCount})...");
                await Task.Delay((int)(lastRetryTime.AddSeconds(retryDelayMultiplier * retryCount).Subtract(DateTime.Now).TotalMilliseconds));
            }

            try
            {
                using var response = await Http.GetAsync($"{SERVER_URL}/{file.FileName}");

                if (!response.IsSuccessStatusCode)
                {
                    if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
                    {
                        UpdateStatus($"Erro: Arquivo não encontrado ({file.FileName}). Esperando 5 segundos...");
                        await Task.Delay(5000);

                        // Reduzir tempo gradualmente até chegar a 0
                        var delay = Math.Max(0, 5000 - (retryCount * 1000));
                        await Task.Delay(delay);
                        retryCount++;
                        continue;
                    }

                    throw new Exception($"Erro HTTP: ${response.StatusCode}");
                }

                // Calcular tamanho do conteúdo para progresso
                long contentLength = response.Content.Headers.ContentLength ?? 0;
                if (contentLength == 0) contentLength = file.Size; // Fallback

                using var stream = await response.Content.ReadAsStreamAsync();
                using var writeStream = new FileStream(Path.Combine(AppDomain.CurrentDomain.BaseDirectory, PATCH_FOLDER_NAME, file.FileName), FileMode.Create, FileAccess.Write, FileShare.None);

                byte[] buffer = new byte[8192];
                int bytesRead;

                while ((bytesRead = await stream.Read(buffer, 0, buffer.Length)) > 0)
                {
                    await writeStream.WriteAsync(buffer, 0, bytesRead);
                    downloadedBytes += bytesRead;
                    progressPercent = (int)((downloadedBytes * 100) / contentLength);

                    // Atualizar UI periodicamente (simulado aqui para performance, idealmente via SignalR ou WebWorker)
                    StateHasChanged(); 
                }

                // Limpar arquivo temporário da memória se houver
                await writeStream.FlushAsync();
                await writeStream.DisposeAsync();

                // Verificar hash novamente após salvar
                if (await FileExistsAndMatchesHash(file))
                {
                    UpdateStatus($"Arquivo '{file.FileName}' salvo e validado com sucesso.");
                }
                else
                {
                    throw new Exception("Integridade do arquivo falhou após o download.");
                }

                files.RemoveAt(0);
                isDownloading = false;
                progressPercent = 0;
                UpdateStatus($"Download concluído: @{file.FileName}. Próximo...");

            }
            catch (Exception ex)
            {
                UpdateStatus($"Falha no download: @{ex.Message}");
                retryCount++;
                await RetryLogic();
            }
        }
    }

    private async Task<bool> FileExistsAndMatchesHash(PatchFile file)
    {
        string path = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, PATCH_FOLDER_NAME, file.FileName);

        if (!File.Exists(path)) return false;

        try
        {
            var hashAlgorithm = System.Security.Cryptography.SHA256.Create();
            var fileStream = File.OpenRead(path);
            var hashValue = hashAlgorithm.ComputeHash(fileStream);
            fileStream.Close();

            string expectedHash = file.Integrity;
            string computedHash = Convert.ToHexString(hashValue).ToLower();

            return computedHash.Equals(expectedHash, StringComparison.OrdinalIgnoreCase);
        }
        catch
        {
            return false;
        }
    }

    private async Task RetryLogic()
    {
        // Lógica de reinício programático se a tela congelar ou internet cair
        // Na prática, isso seria disparado pelo evento 'onerror' do fetch, mas aqui simulamos:
        UpdateStatus("Detectada falha de rede/interrupção. Reiniciando download...");
        await Task.Delay(2000); // Pequeno delay antes de tentar novamente
